set -eu
sudo docker exec quickreels-api-1 node -e 'const Fastify=require("fastify");const jwt=require("@fastify/jwt");const {PrismaClient}=require("@prisma/client");const {loadEnv}=require("./dist/config/env");const {miniAppEnvironment}=require("./dist/config/mini-apps");(async()=>{const env=loadEnv();const db=new PrismaClient({datasources:{db:{url:miniAppEnvironment(env,"talereels").DATABASE_URL}}});const app=Fastify();try{const admin=await db.adminUser.findFirst({where:{status:"ACTIVE",role:"OWNER"},select:{id:true,tokenVersion:true}});if(!admin)throw Error("No active TaleReels owner available for smoke test");await app.register(jwt,{secret:env.JWT_SECRET});const token=app.jwt.sign({sub:admin.id,kind:"admin",appKey:"talereels",tokenVersion:admin.tokenVersion},{expiresIn:"2m"});for(const path of ["/admin/me","/admin/episodes","/admin/platform-sync-jobs?limit=50","/admin/analytics/audience?from=2026-09-16&to=2026-10-15&timezone=Asia%2FShanghai","/admin/analytics/playback-quality?from=2026-09-16&to=2026-10-15&timezone=Asia%2FShanghai","/admin/app-entry-ad-policy?releaseId=default","/admin/app-entry-ad-policies"]){let response=await fetch("http://127.0.0.1:3000/api/talereels/v1"+path,{headers:{authorization:"Bearer "+token},signal:AbortSignal.timeout(15000)});console.log(response.status+" "+path);await response.arrayBuffer()}}finally{await db.$disconnect();await app.close()}})().catch(e=>{console.error(e.message);process.exit(1)})'
